3	namespace App\Http\Controllers\Api\Shopify;
4	
5	use App\Exceptions\Shopify\ShopifyTransportException;
6	use App\Http\Controllers\Api\ApiController;
7	use App\Http\Controllers\Concerns\NormalizesShopDomain;
8	use App\Models\Core\Professional\Professional;
9	use App\Models\Core\Professional\ProfessionalIntegration;
10	use App\Services\Shopify\BrandSignupService;
11	use App\Services\Shopify\Client\ShopifyAdminClient;
12	use App\Services\Shopify\ShopifySetupTokenService;
13	use Illuminate\Http\JsonResponse;
14	use Illuminate\Http\RedirectResponse;
15	use Illuminate\Http\Request;
16	use Illuminate\Support\Arr;
17	use Illuminate\Support\Facades\Http;
18	use Illuminate\Support\Facades\Log;
