20	class ShopifyAppOAuthController extends ApiController
21	{
22	    use NormalizesShopDomain;
23	
24	    public function __construct(
25	        private readonly BrandSignupService $brandSignup,
26	        private readonly ShopifySetupTokenService $setupTokens,
27	        private readonly ShopifyAdminClient $shopifyClient,
28	    ) {}
29	
30	    public function install(Request $request): RedirectResponse|JsonResponse
31	    {
32	        $shop = $this->normalizeShopDomain((string) $request->query('shop', ''));
33	
34	        if ($shop === '') {
35	            return $this->error('Missing shop parameter.', 400);
36	        }
37	
38	        if (! $this->isValidShopDomain($shop)) {
39	            return $this->error('Invalid shop domain.', 400);
40	        }
41	
42	        $apiKey = (string) config('services.shopify.api_key');
43	        $redirectUri = rtrim((string) config('app.url'), '/').'/api/shopify/callback';
44	        $nonce = bin2hex(random_bytes(16));
45	
46	        cache()->put("shopify_oauth_nonce_{$shop}", $nonce, now()->addMinutes(10));
47	
48	        // Managed installation: omit the `scope` parameter so Shopify grants
49	        // every scope declared in Sidest-Embedded/shopify.app.toml
50	        // access_scopes block (pushed via `shopify app deploy`). Passing a
51	        // narrower scope= here would override the toml and short-grant the
52	        // merchant — that's how previous installs ended up without
53	        // read_products despite the toml listing it.
54	        //
55	        // Ref: https://shopify.dev/docs/apps/build/authentication-authorization/access-tokens/authorization-code-grant
56	        $authUrl = "https://{$shop}/admin/oauth/authorize?"
57	            .http_build_query([
58	                'client_id' => $apiKey,
59	                'redirect_uri' => $redirectUri,
60	                'state' => $nonce,
61	            ]);
62	
63	        return redirect()->away($authUrl);
64	    }
65	
66	    public function callback(Request $request): RedirectResponse|JsonResponse
67	    {
68	        $shop = $this->normalizeShopDomain((string) $request->query('shop', ''));
69	        $code = (string) $request->query('code', '');
70	        $state = (string) $request->query('state', '');
71	        $hmac = (string) $request->query('hmac', '');
72	
73	        if ($shop === '' || $code === '' || $state === '' || $hmac === '') {
74	            return $this->error('Missing required OAuth parameters.', 400);
75	        }
76	
77	        if (! $this->isValidHmac($request->query(), (string) config('services.shopify.api_secret'))) {
78	            Log::warning('Shopify OAuth: invalid HMAC', ['shop' => $shop]);
79	
80	            return $this->error('Invalid HMAC signature.', 400);
81	        }
82	
83	        $expectedNonce = cache()->pull("shopify_oauth_nonce_{$shop}");
84	        if ($expectedNonce === null || ! hash_equals($expectedNonce, $state)) {
85	            Log::warning('Shopify OAuth: invalid nonce', ['shop' => $shop]);
86	
87	            return $this->error('Invalid state parameter.', 400);
88	        }
89	
90	        $tokenResponse = Http::post("https://{$shop}/admin/oauth/access_token", [
91	            'client_id' => config('services.shopify.api_key'),
92	            'client_secret' => config('services.shopify.api_secret'),
93	            'code' => $code,
94	        ]);
95	
96	        if (! $tokenResponse->successful()) {
97	            Log::error('Shopify OAuth: token exchange failed', [
98	                'shop' => $shop,
99	                'status' => $tokenResponse->status(),
100	            ]);
101	
102	            return $this->error('Failed to exchange OAuth code for access token.', 502);
103	        }
104	
105	        $accessToken = (string) ($tokenResponse->json('access_token') ?? '');
106	        $scopes = (array) ($tokenResponse->json('scope') ? explode(',', (string) $tokenResponse->json('scope')) : []);
107	
108	        if ($accessToken === '') {
109	            return $this->error('Empty access token received from Shopify.', 502);
110	        }
111	
112	        $shopData = [];
113	        try {
114	            $apiVersion = (string) config('services.shopify.api_version', '2025-01');
115	            $shopResponse = $this->shopifyClient->rest(
116	                method: 'GET',
117	                shopDomain: $shop,
118	                accessToken: $accessToken,
119	                path: "/admin/api/{$apiVersion}/shop.json",
120	            );
121	            $shopData = (array) ($shopResponse->json('shop') ?? []);
122	        } catch (ShopifyTransportException $e) {
123	            Log::warning('Shopify OAuth: shop fetch failed', ['shop' => $shop, 'status' => $e->status]);
124	        }
125	
126	        $shopEmail = strtolower(trim((string) Arr::get($shopData, 'email', '')));
127	        $shopHandle = str_replace('.myshopify.com', '', $shop);
128	        $appHandle = (string) config('services.shopify.app_handle', 'side-st');
129	        $basePath = "https://admin.shopify.com/store/{$shopHandle}/apps/{$appHandle}";
130	
131	        try {
132	            // Path A: Reinstall — existing integration for this shop domain
133	            $existingIntegration = ProfessionalIntegration::query()
134	                ->where('shopify_shop_domain', $shop)
135	                ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
136	                ->first();
137	
138	            if ($existingIntegration) {
139	                $result = $this->brandSignup->handleReinstall($existingIntegration, $accessToken, $shopData, $scopes);
140	
141	                Log::info('Shopify OAuth: reinstall', [
142	                    'professional_id' => (string) $result->professional->id,
143	                    'shop_domain' => $shop,
144	                ]);
145	
146	                return redirect()->away($basePath);
147	            }
148	
149	            // Path B: Existing account — shop email matches a Professional's primary_email (indexed local lookup).
150	            // Users whose Shopify email differs from their Side St email fall through to Path C.
151	            if ($shopEmail !== '') {
152	                $existingProfessional = Professional::whereRaw('lower(primary_email) = ?', [$shopEmail])->first();
153	
154	                if ($existingProfessional) {
155	                    $result = $this->brandSignup->handleExistingBrandConnect(
156	                        $existingProfessional, $shop, $accessToken, $shopData, $scopes
157	                    );
158	
159	                    Log::info('Shopify OAuth: existing account connect', [
160	                        'professional_id' => (string) $result->professional->id,
161	                        'shop_domain' => $shop,
162	                    ]);
163	
164	                    return redirect()->away($basePath);
165	                }
166	            }
167	
168	            // Path C: Fresh install — cache credentials and redirect to setup wizard
169	            $setupToken = $this->setupTokens->create($shop, $accessToken, $shopData, $scopes, $shopEmail);
170	
171	            Log::info('Shopify OAuth: fresh install, redirecting to setup', [
172	                'shop_domain' => $shop,
173	            ]);
174	
175	            return redirect()->away("{$basePath}/setup?shopify_setup_token={$setupToken}");
176	        } catch (\Throwable $e) {
177	            Log::error('Shopify OAuth: callback failed', [
178	                'shop' => $shop,
179	                'error' => $e->getMessage(),
180	            ]);
181	
182	            return $this->error('Failed to process Shopify app installation.', 500);
183	        }
184	    }
