186	    public function setupPrefill(Request $request): JsonResponse
187	    {
188	        $token = trim((string) $request->query('token', ''));
189	
190	        if ($token === '') {
191	            return $this->error('Missing token.', 400);
192	        }
193	
194	        $data = $this->setupTokens->peek($token);
195	
196	        if ($data === null) {
197	            return $this->error('Setup session not found or expired.', 404);
198	        }
199	
200	        $shopData = $data['shop_data'] ?? [];
201	
202	        return $this->success([
203	            'shop_name' => trim((string) Arr::get($shopData, 'name', '')),
204	            'shop_domain' => $data['shop_domain'] ?? '',
205	            'phone' => trim((string) Arr::get($shopData, 'phone', '')),
206	            'address' => [
207	                'address1' => trim((string) Arr::get($shopData, 'address1', '')),
208	                'city' => trim((string) Arr::get($shopData, 'city', '')),
209	                'province' => trim((string) Arr::get($shopData, 'province', '')),
210	                'zip' => trim((string) Arr::get($shopData, 'zip', '')),
211	                'country' => trim((string) Arr::get($shopData, 'country_name', '')),
212	            ],
213	            'country_code' => trim((string) Arr::get($shopData, 'country_code', '')),
214	            'timezone' => trim((string) Arr::get($shopData, 'iana_timezone', '')),
215	        ]);
216	    }
217	
218	    private function isValidShopDomain(string $shop): bool
219	    {
220	        return (bool) preg_match('/^[a-zA-Z0-9\-]+\.myshopify\.com$/', $shop);
221	    }
222	
223	    private function isValidHmac(array $params, string $secret): bool
224	    {
225	        $actual = (string) ($params['hmac'] ?? '');
226	        $filtered = array_filter($params, static fn ($key) => $key !== 'hmac', ARRAY_FILTER_USE_KEY);
227	        ksort($filtered);
228	        $message = http_build_query($filtered);
229	        $expected = hash_hmac('sha256', $message, $secret);
230	
231	        return $actual !== '' && hash_equals($expected, $actual);
232	    }
233	}
