5	// V2: Normalizes Shopify shop domains by stripping protocol, port, and trailing characters to a bare hostname.
6	trait NormalizesShopDomain
7	{
8	    private function normalizeShopDomain(string $value): string
9	    {
10	        $value = mb_strtolower(trim($value));
11	        if ($value === '') {
12	            return '';
13	        }
14	
15	        if (str_contains($value, '://')) {
16	            $value = mb_strtolower(trim((string) parse_url($value, PHP_URL_HOST)));
17	        }
18	
19	        $value = preg_replace('/:\d+$/', '', $value) ?? $value;
20	        $value = trim($value, " \t\n\r\0\x0B./");
21	
22	        return $value;
23	    }
24	}
